import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const EVIDENCE_TYPES = ['통장', '카드', '현금영수증', '전자세금계산서'];

// 품의서는 전표 -> 지출결의서(expense_resolution) -> 품의서 순서로 이어진다 (가정)
const FROM_WHERE = `
  FROM voucher_line vl
  JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id
  JOIN account_item ai ON ai.account_item_id = vl.account_item_id
  LEFT JOIN management_item mi ON mi.management_item_id = vl.management_item_id
  LEFT JOIN project pj ON pj.project_id = vl.project_id
  LEFT JOIN expense_resolution er ON er.expense_resolution_id = jv.expense_resolution_id
  LEFT JOIN purchase_request pr ON pr.purchase_request_id = er.purchase_request_id
  WHERE jv.voucher_date >= CAST(:dateFrom AS date)
    AND jv.voucher_date <= CAST(:dateTo AS date)
    AND (CAST(:managementItemId AS bigint) IS NULL OR vl.management_item_id = CAST(:managementItemId AS bigint))
    AND (CAST(:projectId AS bigint) IS NULL OR vl.project_id = CAST(:projectId AS bigint))
    AND (CAST(:evidenceType AS text) IS NULL OR jv.evidence_type = CAST(:evidenceType AS text))
    AND (CAST(:summary AS text) IS NULL OR vl.summary LIKE '%' || CAST(:summary AS text) || '%')
    AND (CAST(:purchaseRequestId AS bigint) IS NULL OR pr.purchase_request_id = CAST(:purchaseRequestId AS bigint))
`;

function textOf(v: unknown): string | null {
  if (v === undefined || v === null) {
    return null;
  }
  const s = String(v).trim();
  return s === '' ? null : s;
}

function idOf(v: unknown): string | null {
  const s = textOf(v);
  if (s === null) {
    return null;
  }
  if (!/^\d+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '식별자는 숫자여야 합니다.');
  }
  return s;
}

function dateOf(v: unknown, label: string): string {
  const s = textOf(v);
  if (s === null) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 입력해 주세요.');
  }
  if (!DATE_PATTERN.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return s;
}

function intOf(v: unknown, fallback: number): number {
  const s = textOf(v);
  if (s === null) {
    return fallback;
  }
  if (!/^\d+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 정보는 숫자여야 합니다.');
  }
  return Number(s);
}

@Controller('api/v1')
export class FnSfr00807Controller {
  @Get('/management-item-ledgers')
  async listManagementItemLedgers(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const query = checks.queryOf(req.query);
    const dateFrom = dateOf(query['dateFrom'], '조회 시작일');
    const dateTo = dateOf(query['dateTo'], '조회 종료일');
    const evidenceType = textOf(query['evidenceType']);
    if (evidenceType !== null && !EVIDENCE_TYPES.includes(evidenceType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '증빙 유형이 올바르지 않습니다.');
    }
    const summary = textOf(query['summary']);
    if (summary !== null && summary.length > 500) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적요는 500자 이하여야 합니다.');
    }
    const page = intOf(query['page'], 0);
    let size = intOf(query['size'], DEFAULT_SIZE);
    if (size < 1) {
      size = DEFAULT_SIZE;
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const filters = {
      dateFrom,
      dateTo,
      managementItemId: idOf(query['managementItemId']),
      projectId: idOf(query['projectId']),
      evidenceType,
      summary,
      purchaseRequestId: idOf(query['purchaseRequestId']),
    };
    return transaction(async (db) => {
      const periodRows = await db.query(
        'SELECT CAST(:dateFrom AS date) > CAST(:dateTo AS date) AS "invalid"',
        { dateFrom, dateTo },
      );
      if (periodRows[0] && periodRows[0]['invalid'] === true) {
        throw new ApiError(422, 'INVALID_PERIOD', '조회 기간이 올바르지 않습니다. 시작일이 종료일보다 늦습니다.');
      }
      const countRows = await db.query('SELECT COUNT(*) AS "total"' + FROM_WHERE, filters);
      const total = Number(countRows[0]['total']);
      const items = await db.query(
        `SELECT jv.voucher_date AS "voucherDate",
          mi.item_name AS "itemName",
          vl.management_item_value AS "managementItemValue",
          pj.project_name AS "projectName",
          ai.account_name AS "accountName",
          vl.amount AS "amount",
          vl.summary AS "summary",
          jv.evidence_type AS "evidenceType",
          pr.title AS "purchaseTitle"` +
          FROM_WHERE +
          ` ORDER BY jv.voucher_date, jv.journal_voucher_id, vl.line_no
          LIMIT :limit OFFSET :offset`,
        { ...filters, limit: size, offset: page * size },
      );
      return {
        items: items.map((r: Record<string, unknown>) => ({ ...r, amount: Number(r['amount']) })),
        page,
        size,
        total,
      };
    });
  }
}

