import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  Pairs,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const EVIDENCE_OPTIONS: [string, string][] = [
  ['통장', '통장'],
  ['카드', '카드'],
  ['현금영수증', '현금영수증'],
  ['전자세금계산서', '전자세금계산서'],
];

const PAGE_SIZE = 20;

export default function FnSfr00807Page({ role, notify }: PageProps) {
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [managementItemId, setManagementItemId] = useState<number | string>('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [evidenceType, setEvidenceType] = useState('');
  const [summary, setSummary] = useState('');
  const [purchaseRequestId, setPurchaseRequestId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [formError, setFormError] = useState('');
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page | null>(async () => {
    if (applied === null) {
      return null;
    }
    return call<Page>('GET', '/management-item-ledgers', role, undefined, {
      ...applied,
      page: pageNo,
      size: PAGE_SIZE,
    });
  }, [applied, pageNo, role]);

  const search = () => {
    if (!dateFrom || !dateTo) {
      setFormError('조회 시작일과 조회 종료일을 입력해 주세요.');
      return;
    }
    if (dateFrom > dateTo) {
      setFormError('조회 기간이 올바르지 않습니다. 시작일이 종료일보다 늦습니다.');
      return;
    }
    setFormError('');
    setPageNo(0);
    setApplied({
      dateFrom,
      dateTo,
      managementItemId,
      projectId,
      evidenceType,
      summary,
      purchaseRequestId,
    });
  };

  const reset = () => {
    setDateFrom('');
    setDateTo('');
    setManagementItemId('');
    setProjectId('');
    setEvidenceType('');
    setSummary('');
    setPurchaseRequestId('');
    setFormError('');
    setPageNo(0);
    setApplied(null);
  };

  const items = data ? data.items : [];
  const pageSum = items.reduce((sum, r) => sum + Number(r['amount'] ?? 0), 0);

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <p className="big">
          <Num value={data ? data.total : 0} />
        </p>
      </section>
      <section className="box span-4">
        <h2>현재 쪽 금액 합계</h2>
        <p className="big">
          <Num value={pageSum} />
        </p>
      </section>
      <section className="box span-4">
        <h2>조회 기간</h2>
        <p className="big">
          {applied ? (
            <>
              <DateText value={applied['dateFrom']} /> ~ <DateText value={applied['dateTo']} />
            </>
          ) : (
            '-'
          )}
        </p>
      </section>
      <section className="box span-12">
        <h2>관리항목별 장부</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={dateFrom} onChange={setDateFrom} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={dateTo} onChange={setDateTo} />
          </Field>
          <Field label="관리항목">
            <LookupSelect
              table="management_item"
              role={role}
              value={managementItemId}
              onChange={setManagementItemId}
            />
          </Field>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
          </Field>
          <Field label="증빙 유형">
            <Select value={evidenceType} onChange={setEvidenceType} options={EVIDENCE_OPTIONS} />
          </Field>
          <Field label="적요">
            <TextInput value={summary} onChange={setSummary} />
          </Field>
          <Field label="품의서 ID">
            <LookupSelect
              table="purchase_request"
              role={role}
              value={purchaseRequestId}
              onChange={setPurchaseRequestId}
            />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          rows={items}
          empty={loading ? '불러오는 중입니다.' : '조회 조건을 입력하고 조회해 주세요.'}
          onRowClick={(row) => setSelected(row)}
          columns={[
            { key: 'voucherDate', label: '전표일자', render: (r) => <DateText value={r['voucherDate']} /> },
            { key: 'itemName', label: '관리항목명' },
            { key: 'managementItemValue', label: '관리항목값' },
            { key: 'projectName', label: '프로젝트 명칭' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'amount', label: '금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'summary', label: '적요' },
            { key: 'evidenceType', label: '증빙 유형', render: (r) => <Badge value={r['evidenceType']} /> },
            { key: 'purchaseTitle', label: '품의 제목' },
          ]}
        />
        <Pager
          page={data ? data.page : 0}
          size={PAGE_SIZE}
          total={data ? data.total : 0}
          onPage={setPageNo}
        />
      </section>
      {selected ? (
        <Drawer title="장부 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['전표일자', <DateText value={selected['voucherDate']} />],
              ['관리항목명', String(selected['itemName'] ?? '-')],
              ['관리항목값', String(selected['managementItemValue'] ?? '-')],
              ['프로젝트 명칭', String(selected['projectName'] ?? '-')],
              ['계정과목 명칭', String(selected['accountName'] ?? '-')],
              ['금액', <Num value={selected['amount']} />],
              ['적요', String(selected['summary'] ?? '-')],
              ['증빙 유형', <Badge value={selected['evidenceType']} />],
              ['품의 제목', String(selected['purchaseTitle'] ?? '-')],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
